const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Bosumtwi geometry
  const lakeBosumtwi = ee.Geometry.Point([−1.4124, 6.5022]).buffer(4000);

  // 2. Cloud masking function for Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Get Sentinel-2 data for December 2015
  let col2015 = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(lakeBosumtwi)
      .filterDate('2015-12-01', '2015-12-31')
      .map(maskS2Clouds);

  let size2015 = await col2015.size().getInfo();
  console.log(`December 2015 Sentinel-2 Images: ${size2015}`);

  // If no Sentinel-2 data in Dec 2015, try Landsat 8
  let green2015, count2015;
  if (size2015 === 0) {
    console.log('Trying Landsat 8 for 2015...');
    const colL8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(lakeBosumtwi)
        .filterDate('2015-12-01', '2015-12-31')
        .filter(ee.Filter.lt('CLOUD_COVER', 50));

    const sizeL8 = await colL8.size().getInfo();
    console.log(`December 2015 Landsat 8 Images: ${sizeL8}`);

    if (sizeL8 === 0) {
      console.log('No data for December 2015.');
      console.log('<answer>C1</answer>');
      return;
    }

    const img2015 = colL8.median().multiply(0.0000275).add(−0.2);
    green2015 = await img2015.select('SR_B3').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: lakeBosumtwi,
      scale: 3000,
      maxPixels: 1e9
    }).get('SR_B3').getInfo();

    count2015 = await img2015.select('SR_B3').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeBosumtwi,
      scale: 3000,
      maxPixels: 1e9
    }).get('SR_B3').getInfo();
  } else {
    const img2015 = col2015.median();
    green2015 = await img2015.select('B3').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: lakeBosumtwi,
      scale: 3000,
      maxPixels: 1e9
    }).get('B3').getInfo();

    count2015 = await img2015.select('B3').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeBosumtwi,
      scale: 3000,
      maxPixels: 1e9
    }).get('B3').getInfo();
  }

  if (count2015 === 0 || count2015 === null) {
    console.log('No valid pixels for 2015 after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Get Sentinel-2 data for December 2024
  const col2024 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeBosumtwi)
      .filterDate('2024-12-01', '2024-12-31')
      .map(maskS2Clouds);

  const size2024 = await col2024.size().getInfo();
  console.log(`December 2024 Sentinel-2 Images: ${size2024}`);

  if (size2024 === 0) {
    console.log('No data for December 2024.');
    console.log('<answer>C1</answer>');
    return;
  }

  const img2024 = col2024.median();
  const green2024 = await img2024.select('B3').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeBosumtwi,
    scale: 3000,
    maxPixels: 1e9
  }).get('B3').getInfo();

  const count2024 = await img2024.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeBosumtwi,
    scale: 3000,
    maxPixels: 1e9
  }).get('B3').getInfo();

  if (count2024 === 0 || count2024 === null) {
    console.log('No valid pixels for 2024 after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validation and comparison
  console.log(`2015 Green (B3): ${green2015}, Pixels: ${count2015}`);
  console.log(`2024 Green (B3): ${green2024}, Pixels: ${count2024}`);

  if (green2015 === null || green2024 === null || isNaN(green2015) || isNaN(green2024)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (green2024 > green2015) {
    console.log('Water appeared MORE green in 2024.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water did NOT appear more green in 2024.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
